    public function run(): void
    {
        $sira = (int) TehlikeKategorisi::max('sira');

        foreach (self::KATEGORILER as $anahtar => [$ad, $maddeler]) {
            $kategori = TehlikeKategorisi::firstOrCreate(['anahtar' => $anahtar], ['ad' => $ad, 'sira' => ++$sira]);

            foreach ($maddeler as $madde) {
                Tehlike::updateOrCreate(
                    ['tehlike_kategorisi_id' => $kategori->id, 'kod' => $madde['kod']],
                    $madde,
                );
            }

            // Güncellenen ekipman analizi: eski dosyanın bu kategorideki maddeleri kalkar.
            Tehlike::query()->where('tehlike_kategorisi_id', $kategori->id)
                ->where(fn ($q) => collect(self::ONEKLER)->each(fn ($o) => $q->orWhere('kod', 'like', $o.'-%')))
                ->whereNotIn('kod', array_column($maddeler, 'kod'))
                ->delete();
        }
    }
